nc=len(comm_ids); ne=len(edge_ids); ns=len(snaps); nd=len(domains)
W=[sum(w for (_,w) in c['routes']) for c in commodities]
L=1
for w in W: L=lcm(L,w)
coeff=[[0]*ne for _ in range(nc)]
for ci,c in enumerate(commodities):
    wc=W[ci]
    for (ed,w) in c['routes']:
        add=L*w//wc
        for eid in ed: coeff[ci][edge_index[eid]]+=add
q=[[z3.Int('q_%d_%d'%(s,ci)) for ci in range(nc)] for s in range(ns)]
faulty=[z3.Bool('f_%d'%d) for d in range(nd)]
def ff(d): return z3.If(faulty[d],1,0)
base=[]
for s in range(ns):
    for ci in range(nc):
        lo,hi=snaps[s]['bounds'][ci]; base+=[q[s][ci]>=lo,q[s][ci]<=hi]
for s in range(ns):
    for e in range(ne):
        cap=edges[e]['capacity']; expr=None
        for ci in range(nc):
            cf=coeff[ci][e]
            if cf:
                t=cf*q[s][ci]; expr=t if expr is None else expr+t
        if expr is not None: base.append(expr<=L*cap)
def ve(s,metric,target):
    if metric=='demand': return L*q[s][comm_ids.index(target)]
    if metric=='link':
        e=edge_index[target]; expr=None
        for ci in range(nc):
            cf=coeff[ci][e]
            if cf:
                t=cf*q[s][ci]; expr=t if expr is None else expr+t
        return expr if expr is not None else z3.IntVal(0)
    expr=None
    for ci,c in enumerate(commodities):
        if (metric=='ingress' and c['source']==target) or (metric=='egress' and c['target']==target):
            t=L*q[s][ci]; expr=t if expr is None else expr+t
    return expr if expr is not None else z3.IntVal(0)
def maxE(s,metric,target):
    if metric=='demand': return L*snaps[s]['bounds'][comm_ids.index(target)][1]
    if metric=='link':
        e=edge_index[target]; tot=0
        for ci in range(nc):
            cf=coeff[ci][e]
            if cf: tot+=cf*snaps[s]['bounds'][ci][1]
        return tot
    tot=0
    for ci,c in enumerate(commodities):
        if (metric=='ingress' and c['source']==target) or (metric=='egress' and c['target']==target):
            tot+=L*snaps[s]['bounds'][ci][1]
    return tot
for s in range(ns):
    for o in snaps[s]['observations']:
        expr=ve(s,o['metric'],o['target']); loL=L*o['lo']; hiL=L*o['hi']
        if o['domain'] is None:
            base.append(z3.And(expr>=loL,expr<=hiL))
        else:
            d=domains.index(o['domain'])
            mE=maxE(s,o['metric'],o['target'])
            Mup=max(0,mE-hiL); Mlo=max(0,loL)
            base.append(expr<=hiL+Mup*ff(d))
            base.append(expr>=loL-Mlo*ff(d))
sumf=z3.Sum([ff(d) for d in range(nd)])
t=time.time(); o=z3.Optimize(); o.add(base); h=o.minimize(sumf); print('sat?',o.check()); k=o.lower(h); print('k',k,'kmintime',time.time()-t)
basek=base+[sumf==k]
